```iec-st\nFUNCTION_BLOCK FB_BESS_Megapack_Control
VAR_INPUT
    bEnable : BOOL; (* System Enable *)
    rGridVoltage : REAL; (* Grid Voltage [V] *)
    rGridFreq : REAL; (* Grid Frequency [Hz] *)
    rActivePowerCmd : REAL; (* Active Power Command [kW] *)
    rReactivePowerCmd : REAL; (* Reactive Power Command [kVAR] *)
    arrCellVoltages : ARRAY[1..128] OF REAL; (* Individual Cell Voltages [V] *)
    arrCellTemps : ARRAY[1..128] OF REAL; (* Individual Cell Temperatures [C] *)
    rTotalCurrent : REAL; (* Total Pack Current [A] *)
    rAmbientTemp : REAL; (* Ambient Temperature [C] *)
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL; (* BESS Ready for Grid Synch *)
    bGridFormingActive : BOOL; (* Grid-forming Mode Active *)
    rInverterVdcRef : REAL; (* DC Link Voltage Reference [V] *)
    rInverterIdRef : REAL; (* D-axis Current Reference [A] *)
    rInverterIqRef : REAL; (* Q-axis Current Reference [A] *)
    bThermalRunawayAlarm : BOOL; (* Critical Thermal Runaway Warning *)
    bCellBalancingActive : BOOL; (* Balancing Routine Active *)
    arrBalancingCmd : ARRAY[1..128] OF BOOL; (* Cell Balancing Bleed Resistor Commands *)
    rMaxCellTemp : REAL;
    rMinCellVoltage : REAL;
    rMaxCellVoltage : REAL;
    rEstimatedSOC : REAL; (* State of Charge [%] *)
END_VAR

VAR
    i : INT;
    rVoltageSum : REAL;
    rTempDelta : REAL;
    rTempDerivative : ARRAY[1..128] OF REAL;
    arrPrevCellTemps : ARRAY[1..128] OF REAL;
    rMaxTempRiseRate : REAL;
    rCoulombCount : REAL := 500000.0; (* Initial charge in As *)
    rTotalCapacity : REAL := 1000000.0; (* Pack capacity in As *)

    (* PID Controllers for Grid-Forming *)
    rKp_Id : REAL := 1.2;
    rKi_Id : REAL := 0.05;
    rKp_Iq : REAL := 1.5;
    rKi_Iq : REAL := 0.08;
    rIdErrorIntegral : REAL := 0.0;
    rIqErrorIntegral : REAL := 0.0;

    tCycleTimer : TON;
    tThermalSample : TON;
END_VAR

(* --- 1. Cell Monitoring & Statistics --- *)
rMaxCellTemp := -50.0;
rMaxCellVoltage := 0.0;
rMinCellVoltage := 10.0;
rVoltageSum := 0.0;

FOR i := 1 TO 128 DO
    (* Voltage Stats *)
    IF arrCellVoltages[i] > rMaxCellVoltage THEN rMaxCellVoltage := arrCellVoltages[i]; END_IF;
    IF arrCellVoltages[i] < rMinCellVoltage THEN rMinCellVoltage := arrCellVoltages[i]; END_IF;
    rVoltageSum := rVoltageSum + arrCellVoltages[i];

    (* Temp Stats *)
    IF arrCellTemps[i] > rMaxCellTemp THEN rMaxCellTemp := arrCellTemps[i]; END_IF;
END_FOR;

(* --- 2. Thermal Runaway Prediction Cascade --- *)
tThermalSample(IN := NOT tThermalSample.Q, PT := T#1S);
IF tThermalSample.Q THEN
    rMaxTempRiseRate := 0.0;
    FOR i := 1 TO 128 DO
        rTempDelta := arrCellTemps[i] - arrPrevCellTemps[i];
        rTempDerivative[i] := rTempDelta; (* deg C per second *)
        IF rTempDerivative[i] > rMaxTempRiseRate THEN
            rMaxTempRiseRate := rTempDerivative[i];
        END_IF;
        arrPrevCellTemps[i] := arrCellTemps[i];
    END_FOR;

    (* Runaway condition: Temp > 65C OR Temp rising faster than 1C/s *)
    IF rMaxCellTemp > 65.0 OR rMaxTempRiseRate > 1.0 THEN
        bThermalRunawayAlarm := TRUE;
    ELSE
        bThermalRunawayAlarm := FALSE;
    END_IF;
END_IF;

(* --- 3. Cell Balancing Matrix --- *)
(* Active if Voltage spread > 50mV and System Enabled *)
bCellBalancingActive := (rMaxCellVoltage - rMinCellVoltage) > 0.05 AND bEnable;
IF bCellBalancingActive THEN
    FOR i := 1 TO 128 DO
        (* Turn on bleed resistor for cells > min + 20mV *)
        IF arrCellVoltages[i] > (rMinCellVoltage + 0.02) THEN
            arrBalancingCmd[i] := TRUE;
        ELSE
            arrBalancingCmd[i] := FALSE;
        END_IF;
    END_FOR;
ELSE
    FOR i := 1 TO 128 DO arrBalancingCmd[i] := FALSE; END_FOR;
END_IF;

(* --- 4. SOC Calculation (Coulomb Counting) --- *)
(* Simple integral of current over time, assuming 100ms cycle *)
rCoulombCount := rCoulombCount - (rTotalCurrent * 0.1);
rEstimatedSOC := (rCoulombCount / rTotalCapacity) * 100.0;
IF rEstimatedSOC > 100.0 THEN rEstimatedSOC := 100.0;
ELSIF rEstimatedSOC < 0.0 THEN rEstimatedSOC := 0.0; END_IF;

(* --- 5. Grid-Forming Inverter Modulation --- *)
(* Droop Control & Synchronous Reference Frame PI *)
IF bEnable AND NOT bThermalRunawayAlarm AND rEstimatedSOC > 5.0 THEN
    bSystemReady := TRUE;
    bGridFormingActive := TRUE;

    (* Calculate Reference Currents based on Power Commands and Grid Voltage *)
    (* P = 1.5 * Vd * Id --> Id_ref = P_cmd / (1.5 * Vd) (simplified) *)
    IF rGridVoltage > 10.0 THEN
        rInverterIdRef := (rActivePowerCmd * 1000.0) / (1.5 * rGridVoltage);
        rInverterIqRef := (rReactivePowerCmd * 1000.0) / (1.5 * rGridVoltage);
    ELSE
        rInverterIdRef := 0.0;
        rInverterIqRef := 0.0;
    END_IF;

    rInverterVdcRef := rVoltageSum; 
ELSE
    bSystemReady := FALSE;
    bGridFormingActive := FALSE;
    rInverterIdRef := 0.0;
    rInverterIqRef := 0.0;
END_IF;
END_FUNCTION_BLOCK
\n```
